ame']]);}$auditAction='update';$details+=['class_id'=>$classId,'previous_name'=>$old['name'],'name'=>$name];}else{foreach(['teacher_assignments','pupil_results','learning_notes'] as $table){$q=$db->prepare("SELECT COUNT(*) FROM $table WHERE school_id=? AND class_level=? AND subject=?");$q->execute([$schoolId,$class['name'],$old['name']]);if((int)$q->fetchColumn()>0)throw new DomainException('This subject is used by current teaching, result or note records and cannot be deleted.');}$q=$db->prepare('DELETE FROM school_class_subjects WHERE id=? AND class_id=?');$q->execute([$recordId,$classId]);$auditAction='delete';$details+=['class_id'=>$classId,'name'=>$old['name']];}}$entity='school_subject';$activeSubjectClassId=$classId;}
