aved.<?php endif;?></div><?php endif;?><?php if($loadError):?><div class="notice error" role="alert"><?=e($loadError)?></div><?php endif;?><?php if(isset($_GET['permission_updated'])):?><div class="notice success" role="status">School setup access updated.</div><?php endif;?><?php if(in_array($role,['headteacher','director'],true)):?><section class="content-section setup-permissions"><div class="section-heading"><div><div class="eyebrow">TEAM ACCESS</div><h2>School setup permissions</h2><p class="muted">Grant setup access to an admin linked to your school. You can revoke it at any time.</p></div></div><?php if($setupAdmins):?><div class="table-wrap"><table><thead><tr><th>School</th><th>Admin</th><th>Setup access</th><th>Action</th></tr></thead><tbody><?php foreach($setupAdmins as $setupAdmin):?><tr><td><?=e($setupAdmin['school_name'])?></td><td><?=e($setupAdmin['user_name'])?><small><?=e($setupAdmin['email']?:'')?></small></td><td><?=!empty($setupAdmin['active'])?'Granted':'Not granted'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$setupAdmin['school_id']?>"><input type="hidden" name="target_user_id" value="<?=$setupAdmin['user_id']?>"><input type="hidden" name="action" value="<?=!empty($setupAdmin['active'])?'revoke_setup_permission':'grant_setup_permission'?>"><button class="button <?=!empty($setupAdmin['active'])?'danger':'primary'?>" type="submit"><?=!empty($setupAdmin['active'])?'Revoke access':'Grant setup access'?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No linked admins</h3><p>Admins assigned to your school will appear here so you can grant setup access.</p></div><?php endif;?></section><?php endif;?>
