<section class="content-section registry-import"><div class="registry-import-copy"><span class="eyebrow">BULK SETUP</span><h2>Upload class registry</h2><p class="muted">Import streams for classes and subjects already in the system catalog. Class and subject names must match the catalog. Use one row per class and separate streams or subjects with commas.</p><p class="registry-format"><strong>Columns:</strong> Class · Streams · Subjects()</p><a class="button lime registry-template-link" href="class_registry_template.xlsx" download="class_registry_template.xlsx">Download .xlsx template</a></div><form method="post" enctype="multipart/form-data" class="registry-import-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="import_registry"><?=render_school_select('registry-school',$schools)?><div class="registry-file-field"><label for="registry-file">Excel workbook or CSV</label><input id="registry-file" name="registry_file" type="file" accept=".xlsx,.csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/csv" required><small>Up to 10 MB · .xlsx or .csv · up to 500 class rows</small></div><button type="submit" class="button primary">Import registry</button></form></section>
<section class="content-section class-directory"><details class="class-directory-accordion" open><summary class="class-directory-toggle"><span><span class="eyebrow">SCHOOL STRUCTURE</span><strong>Classes</strong></span><span class="class-directory-meta"><span class="count-pill"><?=count($classes)?> classes</span><span class="class-directory-chevron" aria-hidden="true">⌄</span></span></summary><div class="class-directory-content"><div class="registry-search" role="search" aria-label="Search class registry"><div><label for="search-class">Class</label><input id="search-class" type="search" data-search-class placeholder="Search classes" autocomplete="off"></div><div><label for="search-stream">Stream</label><input id="search-stream" type="search" data-search-stream placeholder="Search streams" autocomplete="off"></div><div><label for="search-subject">Subject</label><input id="search-subject" type="search" data-search-subject placeholder="Search subjects" autocomplete="off"></div><button type="button" class="button" data-clear-search>Clear</button></div><p class="registry-search-status muted" data-search-status aria-live="polite"><?=count($classes)?> classes shown</p><p class="empty-state registry-no-results" data-no-search-results hidden>No classes match these search filters.</p><?php if(!$classes):?><div class="empty-state"><h3>No classes yet</h3><p>Create a class to start adding its streams and subjects.</p><button class="button primary" type="button" data-open-add-class>Add your first class</button></div><?php else:?><div class="table-wrap"><table class="setup-class-table"><thead><tr><th scope="col">Class</th><th scope="col">Streams</th><th scope="col">Actions</th></tr></thead><tbody><?php foreach($classes as $class):$classStreams=$streamsByClass[(int)$class['id']]??[];$classSubjects=$subjectsByClass[(int)$class['id']]??[];?><tr data-class-search="<?=e(mb_strtolower($class['name']))?>" data-stream-search="<?=e(mb_strtolower(implode(' ',array_column($classStreams,'name'))))?>" data-subject-search="<?=e(mb_strtolower(implode(' ',array_column($classSubjects,'name'))))?>"><td><strong class="class-name"><?=e($class['name'])?></strong><small class="class-school-name"><?=e($class['school_name'])?></small></td><td><div class="stream-chip-list"><?php if(!$classStreams):?><span class="muted">No streams added</span><?php else:foreach($classStreams as $stream):?><details class="stream-edit"><summary><?=e($stream['name'])?></summary><div class="stream-edit-panel"><form method="post" class="stream-edit-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="edit_stream"><input type="hidden" name="record_id" value="<?=$stream['id']?>"><input type="hidden" name="school_id" value="<?=$class['school_id']?>"><label class="sr-only" for="stream-<?=$stream['id']?>">Edit stream <?=e($stream['name'])?></label><input id="stream-<?=$stream['id']?>" name="name" value="<?=e($stream['name'])?>" maxlength="80" required><button class="button primary" type="submit">Save</button></form><form method="post" onsubmit="return confirm('Delete this stream?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_stream"><input type="hidden" name="record_id" value="<?=$stream['id']?>"><input type="hidden" name="school_id" value="<?=$class['school_id']?>"><button class="button danger" type="submit">Delete stream</button></form></div></details><?php endforeach;endif;?></div><button type="button" class="text-action" data-open-stream="<?=$class['id']?>">Add stream</button></td><td><div class="class-row-actions"><details class="row-actions setup-row-actions"><summary class="button">Edit</summary><form method="post" class="setup-edit-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="edit_class"><input type="hidden" name="record_id" value="<?=$class['id']?>"><input type="hidden" name="school_id" value="<?=$class['school_id']?>"><label class="sr-only" for="class-<?=$class['id']?>">Class name</label><input id="class-<?=$class['id']?>" name="name" value="<?=e($class['name'])?>" maxlength="80" required><button class="button primary" type="submit">Save</button></form></details><button type="button" class="button" data-show-subjects="<?=$class['id']?>" aria-haspopup="dialog">Show subjects <span class="subject-count"><?=count($classSubjects)?></span></button><form method="post" onsubmit="return confirm('Delete this class and its streams and subjects? This is only possible when no active academic records depend on it.')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_class"><input type="hidden" name="record_id" value="<?=$class['id']?>"><input type="hidden" name="school_id" value="<?=$class['school_id']?>"><button type="submit" class="button danger">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></details></section>
<?php foreach($classes as $class):$classSubjects=$subjectsByClass[(int)$class['id']]??[];?><dialog class="subject-dialog" id="subjects-<?=$class['id']?>" aria-labelledby="subject-dialog-title-<?=$class['id']?>"><div class="subject-dialog-head"><div><div class="eyebrow">CLASS SUBJECTS</div><h2 id="subject-dialog-title-<?=$class['id']?>"><?=e($class['name'])?></h2><p class="muted"><?=e($class['school_name'])?> · <?=count($classSubjects)?> subjects</p></div><button type="button" class="icon-button" data-close-dialog aria-label="Close subjects dialog">×</button></div><div class="subject-dialog-body"><?php if($error&&$activeSubjectClassId===(int)$class['id']):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><h3>Subjects for this class</h3><?php if(!$classSubjects):?><div class="subject-empty">No subjects have been added to this class.</div><?php else:?><div class="subject-edit-list"><?php foreach($classSubjects as $subject):?><form method="post" class="subject-edit-form" data-subject-search-item="<?=e(mb_strtolower($subject['name']))?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="edit_subject"><input type="hidden" name="record_id" value="<?=$subject['id']?>"><input type="hidden" name="school_id" value="<?=$class['school_id']?>"><input type="hidden" name="class_id" value="<?=$class['id']?>"><label class="sr-only" for="subject-<?=$subject['id']?>">Edit subject name</label><input id="subject-<?=$subject['id']?>" name="name" value="<?=e($subject['name'])?>" maxlength="100" required><button type="submit" class="button primary">Save</button><button type="submit" name="action" value="delete_subject" class="button danger" formnovalidate onclick="return confirm('Delete this subject?')">Delete</button></form><?php endforeach;?></div><?php endif;?><form method="post" class="subject-add-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_subject"><input type="hidden" name="school_id" value="<?=$class['school_id']?>"><input type="hidden" name="class_id" value="<?=$class['id']?>"><label for="new-subject-<?=$class['id']?>">Add a core subject</label><div class="subject-add-row"><select name="core_subject_id" required><option value="">Choose a core subject</option><?php $coreSubjectsQ=$db->prepare('SELECT sj.id,sj.name FROM academic_class_subjects sj JOIN school_classes c ON c.core_class_id=sj.class_id WHERE c.id=? ORDER BY sj.name');$coreSubjectsQ->execute([(int)$class['id']]);foreach($coreSubjectsQ->fetchAll() as $coreSubject):?><option value="<?=$coreSubject['id']?>"><?=e($coreSubject['name'])?></option><?php endforeach;?></select><input id="new-subject-<?=$class['id']?>" name="name" maxlength="100" placeholder="School display name (optional)"><button type="submit" class="button primary">Add subject</button></div></form></div><div class="subject-dialog-foot"><button type="button" class="button" data-close-dialog>Done</button></div></dialog><?php endforeach;?>
<?php endif;?></div></main></div>
<dialog class="setup-dialog" id="add-class-dialog" aria-labelledby="add-class-title"><form method="post" class="setup-dialog-form"><div class="subject-dialog-head"><div><div class="eyebrow">SCHOOL STRUCTURE</div><h2 id="add-class-title">Add a class</h2><p class="muted">Choose a system class and, if needed, set its display name for your school. Then add streams and subjects.</p></div><button type="button" class="icon-button" data-close-dialog aria-label="Close dialog">×</button></div><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_class"><?php if($error&&$openAddClass):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><div class="setup-dialog-fields"><?=render_school_select('add-class-school',$schools)?><div><label for="core-class-select">System class</label><select id="core-class-select" name="core_class_id" required><option value="">Choose system class</option><?php foreach($db->query('SELECT id,name FROM academic_classes ORDER BY name')->fetchAll() as $coreClass):?><option value="<?=$coreClass['id']?>"><?=e($coreClass['name'])?></option><?php endforeach;?></select></div><div><label for="new-class-name">School display name</label><input id="new-class-name" name="name" maxlength="80" value="<?=($openAddClass)?e($_POST['name']??''):''?>" placeholder="Leave blank to use system name"></div></div><div class="subject-dialog-foot"><button type="button" class="button" data-close-dialog>Cancel</button><button type="submit" class="button primary">Add class</button></div></form></dialog>
<dialog class="setup-dialog" id="add-stream-dialog" aria-labelledby="add-stream-title"><form method="post" class="setup-dialog-form"><div class="subject-dialog-head"><div><div class="eyebrow">CLASS STREAMS</div><h2 id="add-stream-title">Add a stream</h2><p class="muted">Add a stream inside a class, for example Maroon or Red.</p></div><button type="button" class="icon-button" data-close-dialog aria-label="Close dialog">×</button></div><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_stream"><div class="setup-dialog-fields"><?=render_school_select('add-stream-school',$schools)?><div><label for="add-stream-class">Class</label><select id="add-stream-class" name="class_id" required><option value="">Choose class</option><?php foreach($classes as $class):?><option value="<?=$class['id']?>" data-school-id="<?=$class['school_id']?>" <?=$activeStreamClassId===(int)$class['id']?'selected':''?>><?=e($class['name'].' · '.$class['school_name'])?></option><?php endforeach;?></select></div><div><label for="new-stream-name">Stream name</label><input id="new-stream-name" name="name" maxlength="80" required value="<?=($openAddStream)?e($_POST['name']??''):''?>" placeholder="For example, Maroon"></div></div><div class="subject-dialog-foot"><button type="button" class="button" data-close-dialog>Cancel</button><button type="submit" class="button primary" <?=!$classes?'disabled':''?>>Add stream</button></div></form></dialog>
<script>
(()=>{
document.querySelectorAll('[data-show-subjects]').forEach(button=>button.addEventListener('click',()=>document.querySelector('#subjects-'+button.dataset.showSubjects)?.showModal()));
document.querySelectorAll('[data-close-dialog]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog')?.close()));document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()}));
document.querySelector('[data-open-add-class]')?.addEventListener('click',()=>document.querySelector('#add-class-dialog')?.showModal());document.querySelectorAll('[data-open-stream]').forEach(button=>button.addEventListener('click',()=>{const dialog=document.querySelector('#add-stream-dialog');const classSelect=dialog?.querySelector('#add-stream-class');if(classSelect){classSelect.value=button.dataset.openStream;const schoolId=classSelect.selectedOptions[0]?.dataset.schoolId;const school=dialog.querySelector('[name="school_id"]');if(school)school.value=schoolId||'';school?.dispatchEvent(new Event('change'))}dialog?.showModal()}));
const streamDialog=document.querySelector('#add-stream-dialog'),schoolSelect=streamDialog?.querySelector('[name="school_id"]'),classSelect=streamDialog?.querySelector('#add-stream-class');function filterStreamClasses(){if(!schoolSelect||!classSelect)return;const schoolId=schoolSelect.value;[...classSelect.options].forEach(option=>{if(!option.value)return;const visible=!schoolId||option.dataset.schoolId===schoolId;option.hidden=!visible;option.disabled=!visible;if(!visible&&option.selected)classSelect.value=''})}schoolSelect?.addEventListener('change',filterStreamClasses);filterStreamClasses();
const classQuery=document.querySelector('[data-search-class]'),streamQuery=document.querySelector('[data-search-stream]'),subjectQuery=document.querySelector('[data-search-subject]'),searchRows=[...document.querySelectorAll('[data-class-search]')],searchStatus=document.querySelector('[data-search-status]'),searchEmpty=document.querySelector('[data-no-search-results]');function applyRegistrySearch(){const c=(classQuery?.value||'').trim().toLocaleLowerCase(),s=(streamQuery?.value||'').trim().toLocaleLowerCase(),j=(subjectQuery?.value||'').trim().toLocaleLowerCase();let count=0;searchRows.forEach(row=>{const matches=(!c||row.dataset.classSearch.includes(c))&&(!s||row.dataset.streamSearch.includes(s))&&(!j||row.dataset.subjectSearch.includes(j));row.hidden=!matches;if(matches)count++;row.querySelectorAll('.stream-edit').forEach(chip=>{chip.hidden=!!s&&!chip.querySelector('summary')?.textContent.toLocaleLowerCase().includes(s)});});document.querySelectorAll('[data-subject-search-item]').forEach(item=>{item.hidden=!!j&&!item.dataset.subjectSearchItem.includes(j)});if(searchStatus)searchStatus.textContent=`Showing ${count} of ${searchRows.length} classes`;if(searchEmpty)searchEmpty.hidden=searchRows.length===0||count>0;}[classQuery,streamQuery,subjectQuery].forEach(input=>input?.addEventListener('input',applyRegistrySearch));document.querySelector('[data-clear-search]')?.addEventListener('click',()=>{[classQuery,streamQuery,subjectQuery].forEach(input=>{if(input)input.value=''});applyRegistrySearch()});applyRegistrySearch();
<?php if($activeSubjectClassId):?>document.querySelector('#subjects-<?=$activeSubjectClassId?>')?.showModal();<?php endif;?><?php if($openAddClass):?>document.querySelector('#add-class-dialog')?.showModal();<?php endif;?><?php if($openAddStream):?>document.querySelector('#add-stream-dialog')?.showModal();<?php endif;?>
if(!window.schoolSetupAsyncBound){window.schoolSetupAsyncBound=true;document.addEventListener('submit',async event=>{const form=event.target;if(!(form instanceof HTMLFormElement)||form.method.toLowerCase()!=='post')return;event.preventDefault();const submitter=event.submitter;const button=submitter||form.querySelector('[type="submit"]');if(button?.disabled)return;const oldText=button?.textContent;if(button){button.disabled=true;button.textContent='Saving…'}try{const data=submitter?new FormData(form,submitter):new FormData(form);data.set('_async','1');const response=await fetch(form.getAttribute('action')||location.href,{method:'POST',body:data,headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'},credentials:'same-origin'});const raw=await response.text();let result;try{result=JSON.parse(raw)}catch{throw new Error(response.redirected?'Your session may have expired. Sign in again and retry.':'The server returned an unexpected response. Refresh the page and try again.')}if(!response.ok||!result.ok)throw new Error(result.error||'The change could not be saved.');const pageResponse=await fetch(result.url,{headers:{'X-Requested-With':'XMLHttpRequest'},credentials:'same-origin'});if(!pageResponse.ok)throw new Error('Saved, but the updated page could not be loaded. Refresh to see the latest changes.');const parsed=new DOMParser().parseFromString(await pageResponse.text(),'text/html');history.replaceState({},'',result.url);document.documentElement.replaceWith(parsed.documentElement);const scripts=[...document.querySelectorAll('script')];const external=scripts.filter(script=>script.src);let remaining=external.length;const ready=()=>{if(remaining===0)document.dispatchEvent(new Event('DOMContentLoaded'))};scripts.forEach(oldScript=>{const next=document.createElement('script');for(const attr of oldScript.attributes)next.setAttribute(attr.name,attr.value);if(next.src){next.onload=()=>{remaining--;ready()};next.onerror=()=>{remaining--;ready()}}next.textContent=oldScript.textContent;oldScript.replaceWith(next)});ready();}catch(error){let notice=document.querySelector('.async-form-error');if(!notice){notice=document.createElement('div');notice.className='notice error async-form-error';notice.setAttribute('role','alert');document.querySelector('.page-content')?.prepend(notice)}if(notice)notice.textContent=error.message;if(button){button.disabled=false;button.textContent=oldText||'Save'}}});}
})();
</script></body></html>
